/// Every `menu()` declared by a vendored `.dbd`, keyed by its EPICS name.
///
/// This is the table `get_enum_strs` answers a `DBF_MENU` field from: the
/// field's [`FieldDesc::menu`] already points at its choices, and this map
/// exists for the by-name lookups (`.db` loading, `dbpr`).
pub fn menu_choices(menu: &str) -> Option<&'static [&'static str]> {
    Some(match menu {
        "epidFeedbackMode" => MENU_EPID_FEEDBACK_MODE,
        "epidFeedbackState" => MENU_EPID_FEEDBACK_STATE,
        "throttleDRVLC" => MENU_THROTTLE_DRVLC,
        "throttleDRVLS" => MENU_THROTTLE_DRVLS,
        "throttleOV" => MENU_THROTTLE_OV,
        "throttleSTS" => MENU_THROTTLE_STS,
        "throttleSYNC" => MENU_THROTTLE_SYNC,
        "throttleWAIT" => MENU_THROTTLE_WAIT,
        "timestampTST" => MENU_TIMESTAMP_TST,
        _ => return None,
    })
}

